import React, { useRef } from "react";
import { motion, useScroll, useTransform } from "framer-motion";
import { BRAND } from "./Content";
import { ArrowDownRight, Sparkles, Crown, Gem, Truck, ChevronDown } from "lucide-react";

// Gold Particle Component with enhanced animation
const GoldParticle = ({ delay, duration, size, x, y }) => (
  <motion.div
    className="absolute rounded-full pointer-events-none"
    style={{
      width: size,
      height: size,
      left: `${x}%`,
      top: `${y}%`,
      background: `radial-gradient(circle, #d4af37 0%, rgba(212, 175, 55, 0.5) 40%, transparent 70%)`,
    }}
    animate={{
      y: [0, -40, -20, -50, 0],
      x: [0, 15, -10, 5, 0],
      opacity: [0.4, 0.9, 0.6, 0.8, 0.4],
